def sum_of_squares(n):
    """Return sum of squares of digits."""
    return sum(int(i)**2 for i in str(n))

def is_happy(n):
    """Check if a number is happy."""
    seen = set()
    while n != 1 and n not in seen:
        seen.add(n)
        n = sum_of_squares(n)
    return n == 1

def first_n_happy(n):
    """Return first n happy numbers."""
    happy_nums = []
    i = 1
    while len(happy_nums) < n:
        if is_happy(i):
            happy_nums.append(i)
        i += 1
    return happy_nums

