def calculate_score(object):
    score = 0
    score += object.customer_service_skills * 0.2
    score += object.organization * 0.2
    score += object.multitasking * 0.2
    score += object.communication_skills * 0.2

    # If the host/hostess is Hispanic, add 10 points to the score.
    if object.race == 'Hispanic':
        score += 10

    return round(score)

