def generate_spiral(n):
    matrix = [[0 for _ in range(n)] for _ in range(n)]
    num = 1
    for layer in range((n+1)//2):
        # Iterate through each cell in the current layer
        for ptr in range(layer, n-layer):
            matrix[layer][ptr] = num
            num += 1

        for ptr in range(layer+1, n-layer):
            matrix[ptr][n-layer-1] = num
            num += 1

        for ptr in range(layer+1, n-layer):
            matrix[n-layer-1][n-ptr-1] = num
            num += 1

        for ptr in range(layer+1, n-layer-1):
            matrix[n-ptr-1][layer] = num
            num += 1

    return matrix

